  --color-indigo-glow: #8098f9;
  --color-lavender-mist: #c6d7fe;
  --color-midnight-indigo: #0d0f2c;
  --color-deep-indigo: #1f235b;
  --color-forest: #1a280b;
  --color-mint-tint: #ebf6df;
  --color-ember: #470800;
  --color-saffron: #42230a;
  --color-buttercream: #fffadb;
